import{_ as l,a0 as r,w as o,s as p,ao as h,I as n,x as i,a1 as a,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"如何在任何地方使用 Vim 編輯器輸入文本 | LCTT x X-CMD","titleTemplate":false,"description":"如何在任何地方使用 Vim 編輯器輸入文本 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在任何地方使用 Vim 編輯器輸入文本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在任何地方使用 Vim 編輯器輸入文本 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180501 How To Use Vim Editor To Input Text Anywhere","title":"如何在任何地方使用 Vim 編輯器輸入文本","tag":"201805","desc":""},"relativePath":"201805/20180501 How To Use Vim Editor To Input Text Anywhere.md","filePath":"[post].md"}'),d={name:"201805/20180501 How To Use Vim Editor To Input Text Anywhere.md"};function m(g,e,u,c,k,w){const t=r("Link");return o(),p("div",null,[e[15]||(e[15]=h('<h1 id="如何在任何地方使用-vim-編輯器輸入文本" tabindex="-1">如何在任何地方使用 Vim 編輯器輸入文本 <a class="header-anchor" href="#如何在任何地方使用-vim-編輯器輸入文本" aria-label="Permalink to “如何在任何地方使用 Vim 編輯器輸入文本”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/05/vim-anywhere-720x340.png" alt=""></p><p>各位 Vim 使用者大家好！今天，我這裏有個好消息告訴大家。我會向大家介紹 <strong>Vim-anywhere</strong>，這是一個簡單的腳本，它允許你使用 Vim 編輯器在 Linux 中的任何地方輸入文本。這意味着你能簡單地調用自己最愛的 Vim 編輯器，輸入任何你所想的，並將這些文本粘貼到任意的應用和網站中。這些文本將在剪貼板可用，直到你重啓了系統。這個工具對那些喜歡在非 Vim 環境中使用 Vim 鍵位綁定的人來説十分有用。</p><h3 id="在-linux-中安裝-vim-anywhere" tabindex="-1">在 Linux 中安裝 Vim-anywhere <a class="header-anchor" href="#在-linux-中安裝-vim-anywhere" aria-label="Permalink to “在 Linux 中安裝 Vim-anywhere”">​</a></h3><p>Vim-anywhere 工具可以運行在任何基於 GNOME（或其他衍生品）的 Linux 發行版上。另外，確保你已經安裝了下面的依賴。</p><ul><li>Curl</li><li>Git</li><li>gVim</li><li>xclip</li></ul><p>比如，你可以用下面的命令在 Ubuntu 中安裝這些工具：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install curl git vim-gnome xclip</span></span></code></pre></div><p>然後運行如下的命令來安裝 Vim-anywhere：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -fsSL https://raw.github.com/cknadler/vim-anywhere/master/install | bash</span></span></code></pre></div><p>Vim-anywhere 到此已經安裝完成。現在我們來看看如何使用它。</p><h3 id="在任何地方使用-vim-編輯器輸入文本" tabindex="-1">在任何地方使用 Vim 編輯器輸入文本 <a class="header-anchor" href="#在任何地方使用-vim-編輯器輸入文本" aria-label="Permalink to “在任何地方使用 Vim 編輯器輸入文本”">​</a></h3><p>假如你需要創建一個 word 文檔。但是你更願意使用 Vim 編輯器，而不是 LibreOffice。沒問題，這裏 Vim-anywhere 就派上用場了。Vim-anywhere 自動化了整個流程。它僅僅簡單地調用 Vim 編輯器，所以你能寫任何你所想的，然後將之粘貼到 .doc 文件中。</p><p>讓我給你展示一個用例。打開 LibreOffice 或者你選的任何圖形文本編輯器。然後打開 Vim-anywhere。你只需要按下 <code>CTRL+ALT+V</code> 即可。它將會打開 gVim 編輯器。按下 <code>i</code> 切換到交互模式然後輸入文本。完成之後，鍵入 <code>:wq</code> 關閉並保存文件。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/05/vim-anywhere-1-1.png" alt=""></p><p>這些文本會在剪貼板中可用，直到你重啓了系統。在你關閉編輯器之後，你之前的應用會重新佔據主界面。你只需按下 <code>CTRL+P</code> 將文本粘貼進去。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/05/vim-anywhere-2.png" alt=""></p><p>這僅僅只是一個例子。你甚至可以使用 Vim-anywhere 在煩人的 web 表單或者其他應用上進行輸入。一旦 Vim-anywhere 被調用，它將會打開一個緩衝區。關閉 Vim-anywhere 之後，緩衝器內的內容會自動複製到你的剪貼板中，之前的應用會重新佔據主界面。</p><p>Vim-anywhere 在被調用的時候會在 <code>/tmp/vim-anywhere</code> 中創建一個臨時文件。這些臨時文件會一致保存着，直到你重啓了系統，併為你提供臨時的歷史記錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls /tmp/vim-anywhere</span></span></code></pre></div><p>你可以用下面的命令重新打開最近的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vim $( ls /tmp/vim-anywhere | sort -r | head -n 1 )</span></span></code></pre></div><h4 id="更新-vim-anywhere" tabindex="-1">更新 Vim-anywhere <a class="header-anchor" href="#更新-vim-anywhere" aria-label="Permalink to “更新 Vim-anywhere”">​</a></h4><p>運行下面的命令來更新 Vim-anywhere：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ~/.vim-anywhere/update</span></span></code></pre></div><h4 id="更改快捷鍵" tabindex="-1">更改快捷鍵 <a class="header-anchor" href="#更改快捷鍵" aria-label="Permalink to “更改快捷鍵”">​</a></h4><p>默認調用 Vim-anywhere 的鍵位是 <code>CTRL+ALT+V</code>。你可以用 <code>gconf</code> 工具將其更改為任何自定義的鍵位綁定。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gconftool -t str --set /desktop/gnome/keybindings/vim-anywhere/binding &lt;custom binding&gt;</span></span></code></pre></div><h4 id="卸載-vim-anywhere" tabindex="-1">卸載 Vim-anywhere <a class="header-anchor" href="#卸載-vim-anywhere" aria-label="Permalink to “卸載 Vim-anywhere”">​</a></h4><p>可能有些人覺得每次打開 Vim 編輯器，輸入一些文本，然後將文本複製到其他應用中是沒有意義也毫無必要的。</p><p>如果你不覺得這個工具有用，只需使用下面的命令來卸載它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ~/.vim-anywhere/uninstall</span></span></code></pre></div><hr>',33)),n("p",null,[e[1]||(e[1]=i("via: ",-1)),a(t,{href:"https://www.ostechnix.com/how-to-use-vim-editor-to-input-text-anywhere/"},{default:s(()=>[...e[0]||(e[0]=[i("https://www.ostechnix.com/how-to-use-vim-editor-to-input-text-anywhere/",-1)])]),_:1})]),n("p",null,[e[6]||(e[6]=i("作者：",-1)),a(t,{href:"https://www.ostechnix.com/author/sk/"},{default:s(()=>[...e[2]||(e[2]=[i("SK",-1)])]),_:1}),e[7]||(e[7]=i(" 選題：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:s(()=>[...e[3]||(e[3]=[i("lujun9972",-1)])]),_:1}),e[8]||(e[8]=i(" 譯者：",-1)),a(t,{href:"https://github.com/paperzhang"},{default:s(()=>[...e[4]||(e[4]=[i("paperzhang",-1)])]),_:1}),e[9]||(e[9]=i(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:s(()=>[...e[5]||(e[5]=[i("wxy",-1)])]),_:1})]),n("p",null,[e[12]||(e[12]=i("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[10]||(e[10]=[i("LCTT",-1)])]),_:1}),e[13]||(e[13]=i(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:s(()=>[...e[11]||(e[11]=[i("Linux中國",-1)])]),_:1}),e[14]||(e[14]=i(" 榮譽推出",-1))])])}const V=l(d,[["render",m]]);export{f as __pageData,V as default};
